contact = {}print("welcome to conatct book")while True:    action = input("""              1. Add contact          2. view contact          3. search contact          4. delete contact          5. quit          choose(1-5)    """)    if action == "1":        name = input("enter name: ")        phone = input("enter phone:")        email = input("enter email:")        contact[name] = {        "phone": phone,        "email": email    }    print("contact saved")    if action == "2":        for name, detail in contact.items():                print("\nName:", name)                print("phone:", detail["phone"])                print("email:", detail["email"])        else:            if not contact:                print("no contact found")    if action == "3":        search_name = input("enter contact name")        if search_name in contact:            print("\nName:", search_name)            print("phone:", contact[search_name]["phone"])            print("email:", contact[search_name]["email"])        else:            print("contact not found")    if action == "4":        remove_name = input("which contact to remove?")        if remove_name in contact:            del contact[remove_name]            print("contact removed")        else:            print("contact not found")    elif action == "5":        print("goodbye")        break